const r=await tools.exec_command({cmd:"python - <<'PY'
import csv,collections,datetime,ast
es=list(csv.DictReader(open('/app/dataset/employees.csv'))); emp={e['PESEL']:e for e in es}
ts=list(csv.DictReader(open('/app/dataset/tasks.csv'))); task={int(t['task_id']):int(t['pay_per_completion']) for t in ts}
rs=list(csv.DictReader(open('/app/dataset/timesheet.csv')))
print('Employee IDs')
for eid,n in sorted(collections.Counter(r['employee_id'] for r in rs).items(),key=lambda x:-x[1]):
 print(eid,n,'valid' if eid in emp else 'INVALID')
print('Invalid dates')
for d,n in sorted(collections.Counter(r['date'] for r in rs).items()):
 try:datetime.date.fromisoformat(d)
 except:print(d,n)
print('Zero hours',sum(int(r['hours_worked'])==0 for r in rs))
print('Salary ratio')
ratios=collections.Counter()
for r in rs:
 if r['employee_id'] in emp:
  h=int(r['hours_worked']); base=h*float(emp[r['employee_id']]['hourly_rate']); salary=float(r['salary_amount'])
  if base:ratios[round(salary/base,4)]+=1
print(ratios.most_common(20))
print('exact salary base',ratios[1.0], 'of',sum(ratios.values()))
print('task list parse')
bad=[];unknown=[];mismatch=[];matches=0
for r in rs:
 try:tasks=ast.literal_eval(r['performed_tasks']); assert isinstance(tasks,list)
 except:bad.append((r['id'],r['performed_tasks'],r['bonus']));continue
 un=[t for t in tasks if t not in task]
 if un:unknown.append((r['id'],tasks,float(r['bonus']),sum(task.get(t,0) for t in tasks)))
 else:
  b=sum(task[t] for t in tasks)
  if b!=float(r['bonus']): mismatch.append((r['id'],tasks,b,float(r['bonus'])))
  else:matches+=1
print('bad',len(bad),bad)
print('unknown',len(unknown),unknown[:100])
print('mismatch',len(mismatch),mismatch[:100])
print('matches',matches)
print('First Tuesdays')
for d in ['2025-03-04','2025-04-01','2025-05-06','2025-06-03']:
 rows=[r for r in rs if r['date']==d];c=collections.Counter(r['employee_id'] for r in rows)
 print(d,'rows',len(rows),'ids',len(c),'valid',len(set(c)&set(emp)),'missing',set(emp)-set(c),'repeated',[(k,v) for k,v in c.items() if v>1])
PY",max_output_tokens:15000});text(r.output);

