"""Calculate monthly cleaning-service pay from the source CSV files."""

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(name: str) -> list[dict[str, str]]:
    with (DATASET / name).open(newline="", encoding="utf-8") as file:
        return list(csv.DictReader(file))


def _first_weekday(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def answer() -> dict[str, list[int]]:
    employees = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in _read_csv("employees.csv")
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }
    timesheet = _read_csv("timesheet.csv")

    # The earliest valid record establishes the weekday of each monthly start.
    valid_dates = []
    for row in timesheet:
        try:
            valid_dates.append(date.fromisoformat(row["date"]))
        except ValueError:
            pass
    earliest = min(valid_dates)
    latest = max(valid_dates)
    starts = []
    year, month = earliest.year, earliest.month
    while (year, month) <= (latest.year, latest.month):
        starts.append(_first_weekday(year, month, earliest.weekday()))
        year, month = (year + 1, 1) if month == 12 else (year, month + 1)

    totals: dict[str, dict[date, Decimal]] = defaultdict(
        lambda: defaultdict(Decimal)
    )
    seen_shifts = set()
    for row in timesheet:
        pesel = row["employee_id"]
        if pesel not in employees:
            continue
        try:
            work_date = date.fromisoformat(row["date"])
            hours = Decimal(row["hours_worked"])
        except (ValueError, ArithmeticError):
            continue
        if not 0 <= hours <= 24:
            continue

        # Repeated records have different row IDs but identical shift data.
        shift = tuple(value for key, value in row.items() if key != "id")
        if shift in seen_shifts:
            continue
        seen_shifts.add(shift)

        period_start = max((start for start in starts if start <= work_date), default=None)
        if period_start is None:
            continue

        # A malformed bracket can be repaired because task IDs are three digits.
        # Unknown task IDs have no defined bonus and contribute nothing.
        task_ids = (int(text) for text in re.findall(r"\d+", row["performed_tasks"]))
        bonus = sum((task_pay.get(task_id, Decimal(0)) for task_id in task_ids),
                    Decimal(0))
        totals[pesel][period_start] += hours * employees[pesel] + bonus

    return {
        pesel: [
            int(totals[pesel][start].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for start in starts
        ]
        for pesel in employees
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as file:
        json.dump(answer(), file)

